        --panel: #141b31;
        --panel-strong: #1b2542;
        --border: #32406b;
        --text: #eef2ff;
        --muted: #b7c0e0;
        --accent: #7dd3fc;
        --accent-strong: #38bdf8;
        --shadow: 0 18px 45px rgba(0, 0, 0, 0.35);
