          linear-gradient(180deg, #0a0f1d 0%, var(--bg) 100%);
        color: var(--text);
      }

      .skip-link {
        position: absolute;
        left: 1rem;
        top: 1rem;
        transform: translateY(-200%);
        padding: 0.75rem 1rem;
        border-radius: 999px;
        background: var(--accent);
        color: #001018;
        font-weight: 700;
        text-decoration: none;
      }

      .skip-link:focus {
        transform: translateY(0);
      }

