        margin-bottom: 2rem;
        padding: 2rem;
        border: 1px solid rgba(125, 211, 252, 0.18);
        border-radius: 24px;
        background: linear-gradient(180deg, rgba(20, 27, 49, 0.92), rgba(10, 15, 29, 0.96));
        box-shadow: var(--shadow);
      }

      h1 {
        margin: 0 0 0.75rem;
        font-size: clamp(2rem, 4vw, 3rem);
        line-height: 1.1;
      }

      .hero p {
        margin: 0;
        max-width: 62ch;
        color: var(--muted);
        font-size: 1.05rem;
        line-height: 1.6;
      }

      .faq-list {
        display: grid;
        gap: 1rem;
      }

      .example {
        border: 1px solid var(--border);
        border-radius: 20px;
        background: linear-gradient(180deg, rgba(27, 37, 66, 0.96), rgba(20, 27, 49, 0.92));
        box-shadow: var(--shadow);
        overflow: hidden;
      }

      .question {
        display: flex;
        align-items: center;
        justify-content: space-between;
        gap: 1rem;
        width: 100%;
        padding: 1.2rem 1.25rem;
        border: 0;
        background: transparent;
        color: var(--text);
        font: inherit;
        font-size: 1.05rem;
        font-weight: 700;
        text-align: left;
        cursor: pointer;
      }

      .question:hover {
        background: rgba(125, 211, 252, 0.06);
      }

      .question:focus-visible {
        outline: 3px solid var(--accent);
        outline-offset: -3px;
      }

